/// `value`.


/// Replaces the bound vars in a canonical binder with var values.




fn highest_var_in_clauses<'tcx>(c: ty::Clauses<'tcx>) -> usize {
    
    
    let mut visitor = HighestVarInClauses { max_var: 0 };
    c.visit_with(&mut visitor);
    visitor.max_var
}


